+            .data
+            .into_raw_view()
+            .map_err(|_| ext_value_decode!("routed_experts: unresolved frame"))?;
+        let (&num_rows, shape_per_row) = rows
+            .shape
+            .split_first()
+            .ok_or_else(|| ext_value_decode!("routed_experts: missing row dimension"))?;
